  const radar = {
    ...STARTER,
    parts: [
      { ...STARTER.parts[0], type: 1600 },
      { ...STARTER.parts[1], type: 5001 },
    ],
  };
  expect(viewerSelectionError(radar, true, profile)).toBe(
    'Do not have all the parts for this tank',
