  expect(viewerSelectionError(radar, true, { ...profile, unlockedParts: [5001] })).toBe('');
  expect(viewerSelectionError(STARTER, true, { ...profile, level: 6, unlockedParts: [] })).toBe(
    'Do not have all the parts for this tank',
